BEGIN;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM wbs_insurance_pc_mapping_pre_admission_observation) OR EXISTS(SELECT 1 FROM wbs_insurance_pc_mapping_proposal) OR EXISTS(SELECT 1 FROM wbs_insurance_pc_mapping_approval) OR EXISTS(SELECT 1 FROM wbs_insurance_pc_mapping_decision_trace) THEN RAISE EXCEPTION 'Cannot remove Insurance PC mapping Controller workflow while evidence exists' USING ERRCODE='55000';END IF;END $$;
REVOKE EXECUTE ON FUNCTION refs_record_wbs_insurance_pc_mapping_pre_admission(uuid,uuid,jsonb,jsonb),refs_propose_wbs_insurance_pc_mapping_hash(uuid,uuid,uuid,text,text),refs_create_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid,text,text,text,text),refs_approve_wbs_insurance_pc_mapping_hash(uuid,uuid,uuid,bigint,text,text,uuid,text,date,date,text),refs_approve_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid,bigint,text,text,uuid,text,date,date,text,text,text),refs_read_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid),refs_read_wbs_insurance_pc_mapping_trace(uuid,uuid,text,date),refs_read_wbs_insurance_pc_mapping_admission_resume(uuid,uuid,uuid,text,uuid,text,text) FROM refs_app;
DROP FUNCTION refs_read_wbs_insurance_pc_mapping_admission_resume(uuid,uuid,uuid,text,uuid,text,text);DROP FUNCTION refs_read_wbs_insurance_pc_mapping_trace(uuid,uuid,text,date);DROP FUNCTION refs_read_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid);DROP FUNCTION refs_approve_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid,bigint,text,text,uuid,text,date,date,text,text,text);DROP FUNCTION refs_approve_wbs_insurance_pc_mapping_hash(uuid,uuid,uuid,bigint,text,text,uuid,text,date,date,text);DROP FUNCTION refs_create_wbs_insurance_pc_mapping_proposal(uuid,uuid,uuid,text,text,text,text);DROP FUNCTION refs_propose_wbs_insurance_pc_mapping_hash(uuid,uuid,uuid,text,text);
DROP FUNCTION refs_record_wbs_insurance_pc_mapping_pre_admission(uuid,uuid,jsonb,jsonb);
DROP TABLE wbs_insurance_pc_mapping_decision_trace;DROP TABLE wbs_insurance_pc_mapping_approval;DROP TABLE wbs_insurance_pc_mapping_proposal;DROP TABLE wbs_insurance_pc_mapping_pre_admission_row;DROP TABLE wbs_insurance_pc_mapping_pre_admission_observation;DROP FUNCTION refs_validate_wbs_insurance_pre_admission_observation();
UPDATE permission_catalog SET active=false,effective_to=clock_timestamp(),version=version+1 WHERE permission_code IN ('WBS.INSURANCE.PC_MAPPING.VIEW','WBS.INSURANCE.PC_MAPPING.PROPOSE','WBS.INSURANCE.PC_MAPPING.APPROVE');
COMMIT;
